import java.util.HashMap;
import java.util.Map;

class LruCache<K, V> {
    private static class Node<K, V> {
        K key; V value;
        Node<K, V> prev, next;
        Node(K k, V v) { key = k; value = v; }
    }

    private final int capacity;
    private final Map<K, Node<K, V>> map = new HashMap<>();
    private final Node<K, V> head = new Node<>(null, null); // MRU sentinel
    private final Node<K, V> tail = new Node<>(null, null); // LRU sentinel

    LruCache(int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("capacity > 0");
        this.capacity = capacity;
        head.next = tail; tail.prev = head;
    }

    public synchronized V get(K key) {
        Node<K, V> n = map.get(key);
        if (n == null) return null; // miss: no reorder
        moveToHead(n);              // hit: read mutates order
        return n.value;
    }

    public synchronized void put(K key, V value) {
        Node<K, V> n = map.get(key);
        if (n != null) { n.value = value; moveToHead(n); return; }
        Node<K, V> fresh = new Node<>(key, value);
        map.put(key, fresh);
        addAfterHead(fresh);
        if (map.size() > capacity) {
            Node<K, V> victim = tail.prev;
            removeNode(victim);
            map.remove(victim.key); // evict LRU: tail.prev
        }
    }

    private void moveToHead(Node<K, V> n) { removeNode(n); addAfterHead(n); }
    private void addAfterHead(Node<K, V> n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }
    private void removeNode(Node<K, V> n) {
        n.prev.next = n.next; n.next.prev = n.prev;
        n.prev = n.next = null; // fail fast on double-remove bugs
    }
}
